WITH employees_by_department AS (SELECT dept_id, SUM(salary) AS total_salary, COUNT(DISTINCT salary) AS unique_depts FROM employees WHERE LENGTH(email) >= 7 GROUP BY dept_id) SELECT d.id, d.location, d.dept_name, ebd.total_salary, ebd.unique_depts FROM departments d INNER JOIN employees_by_department ebd ON d.id = ebd.dept_id WHERE ebd.unique_depts > 10
